  "recovered_c": "uint64_t fn_08(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint32_t h = 0xffffffff;\n  for (size_t i = 0; i < len; i++) {\n    h = h ^ in[i];\n    for (uint b = 0; b < 8; b++) {\n      h = -(h & 1) & 0xf7179bf5 ^ h >> 1;\n    }\n  }\n  return (uint64_t)~h;\n}"
